/**
 * Compose→terraform bridge for `displayBlocks`/`recordCreateDisplayBlocks`.
 * `serializeDisplayBlocks` (`display-blocks.ts`) turns the authored
 * `DisplayBlock[]` into the GraphQL-compose wire shape consumed by `to-tf`
 * payloads — this module maps THAT wire shape into `AppLayoutSectionWire[]`,
 * the shape `viewToTf`/`layoutToTf` (`entities/view/to-tf.ts`) already knows
 * how to emit as `elementum_layout`.
 *
 * Only `field`/`group` blocks have an `elementum_layout` equivalent — the
 * provider's `sections` schema has no `widget`/`comments` section type (see
 * `entities/view/types.ts`'s `SECTION_TYPE_TO_WIRE`). `widget`/`comments`
 * blocks are diagnosed and dropped individually rather than killing the
 * whole payload. `AppLayoutSectionWire` groups are flat (`fields` only) —
 * a `group` nested inside a `group` is diagnosed and dropped (its own
 * contents only; the outer group keeps its direct fields), since there is
 * no nested-section shape to target.
 *
 * This is a pure, entity-agnostic transform (it knows nothing about apps or
 * elements) — kept alongside `display-blocks.ts` rather than under
 * `entities/element/`.
 */
import type { AppLayoutSectionWire } from "../view/to-tf.js";
/**
 * Maps serialized `displayBlocks` (the `Record<string, unknown>[]` shape
 * `serializeDisplayBlocks` produces) into `elementum_layout` group sections.
 *
 * - A top-level `GROUP` block → one section (`name`/`icon`/`color`/
 *   `maxColumns` carried over, `fields` from its direct `FIELD` children).
 * - Top-level `FIELD` blocks with no enclosing group are collected into one
 *   implicit group section named `"Details"` (the target shape requires a
 *   non-empty section name — see `IMPLICIT_GROUP_NAME`).
 *   Intentionally always appended LAST, after every named `GROUP` section,
 *   regardless of where the bare fields appeared relative to groups in the
 *   authored list — e.g. `[field, group]` renders as
 *   `[group, implicit-field-group]`. A single implicit group has no natural
 *   authored position of its own (it isn't one authored block, it's the
 *   union of every bare field), so a fixed, deterministic position was
 *   chosen over trying to infer one from interleaving.
 * - `WIDGET`/`COMMENTS` blocks (top-level or nested) and nested `GROUP`
 *   blocks are diagnosed and dropped individually; everything else mappable
 *   in the same payload still lands. A block with no recognizable shape at
 *   all (not a record, or missing/malformed `properties.type`) is likewise
 *   diagnosed and dropped rather than silently ignored.
 */
export declare function displayBlocksToLayoutSections(blocks: readonly unknown[], where: string, diagnostics: string[]): AppLayoutSectionWire[];
